/* Merges the Fit Tag Encyclopedia V2 (tools/fit-tag-encyclopedia-v2.txt) into js/data/taxonomy.js.
   Existing tags keep their live data (operator counts, stage, definition); new tags get their category,
   group, framework area, and the stage most tags in the same group already use. usage: node tools/merge-encyclopedia.js */
const fs = require('fs'), path = require('path');
const file = path.join(__dirname, '..', 'js', 'data', 'taxonomy.js');
global.window = global; global.RN = {};
eval(fs.readFileSync(file, 'utf8'));
const lib = RN.data.tagLibrary, roleGroups = RN.data.roleGroups;
const CAT = { 'Sales Leadership': 'sales_leadership', Marketing: 'marketing', 'Revenue Operations': 'revenue_operations', 'Sales Enablement': 'sales_enablement', 'Customer Success & Growth': 'customer_success_growth', 'AI GTM': 'ai_gtm', Partnerships: 'partnerships', Sellers: 'sellers' };
const AX = { sales_leadership: 'Win deals', sellers: 'Win deals', marketing: 'Generate demand', partnerships: 'Generate demand', revenue_operations: 'Systems & data', ai_gtm: 'Systems & data', sales_enablement: 'Build the team', customer_success_growth: 'Retain & expand' };
const key = (s) => s.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, ' ').trim();
const byKey = new Map(lib.map((t) => [key(t.v), t]));
const rows = fs.readFileSync(path.join(__dirname, 'fit-tag-encyclopedia-v2.txt'), 'utf8').split('\n').filter((l) => l && !l.startsWith('#'))
  .map((l) => { const [c, g, tags] = l.split(' | '); return { c: CAT[c.trim()], g: g.trim(), tags: tags.split(' · ').map((s) => s.trim()).filter(Boolean) }; });
// The stage most existing tags in a group use
const stageOf = {};
rows.forEach((r) => { const cnt = {}; r.tags.forEach((t) => { const x = byKey.get(key(t)); if (x && x.stage) cnt[x.stage] = (cnt[x.stage] || 0) + 1; }); const best = Object.entries(cnt).sort((a, b) => b[1] - a[1])[0]; stageOf[r.c + '|' + r.g] = best ? best[0] : ''; });
// Groups whose tags have no stage yet sit where the framework's stage descriptions put that work
const GROUP_STAGE = {
  Awareness: ['Positioning & Messaging', 'Events & Field', 'Co-Marketing', 'Ecosystem & Community'],
  Engage: ['Account-Based Marketing', 'Paid Channels', 'Demand Generation', 'Outbound & Prospecting AI', 'Lead Management & Routing', 'Prospecting & Pipeline Build', 'Lead & Account Intelligence'],
  Qualify: ['Discovery & Qualification', 'Competitive & Win Rate', 'Pipeline & Forecast', 'Forecasting & Revenue AI', 'Pipeline Management', 'Sales Intelligence & Coaching'],
  Commit: ['Deal Execution', 'Deal Execution & Closing', 'Commercial & Pricing', 'Co-Sell & Revenue Motion', 'Business Development', 'Content & Proposal AI'],
  Onboard: ['Onboarding & Implementation'],
  Adopt: ['Churn Management', 'Customer Engagement', 'Customer Health', 'Retention & Renewal', 'Voice of Customer', 'Post-Sale Strategy'],
  Expand: ['Expansion Motion', 'Advocacy & Community'],
};
const groupStage = (g) => Object.keys(GROUP_STAGE).find((st) => GROUP_STAGE[st].includes(g)) || 'foundation';
let added = 0, entries = 0;
rows.forEach((r) => r.tags.forEach((t) => {
  entries++;
  const x = byKey.get(key(t));
  if (x) { if (!x.g && x.c === r.c) x.g = r.g; return; }
  const n = { v: t, l: t, c: r.c, g: r.g, axis: AX[r.c] || '', stage: stageOf[r.c + '|' + r.g] || '', d: '', n: 0 };
  byKey.set(key(t), n); lib.push(n); added++;
}));
lib.forEach((t) => { if (!t.stage && t.g) t.stage = groupStage(t.g); });
lib.sort((a, b) => b.n - a.n || a.l.localeCompare(b.l));
fs.writeFileSync(file, '/* Generated by tools/build-taxonomy.js and tools/merge-encyclopedia.js: fit tag library (live tags + Fit Tag Encyclopedia V2). */\nwindow.RN = window.RN || {}; RN.data = RN.data || {};\nRN.data.tagLibrary = ' + JSON.stringify(lib) + ';\nRN.data.roleGroups = ' + JSON.stringify(roleGroups || {}) + ';\n');
console.log('encyclopedia entries', entries, 'added', added, 'library now', lib.length, 'groups', rows.length);
